//! Token usage and cost accounting for local and remote LLM calls.

use serde::{Deserialize, Serialize};
use std::ops::{Add, AddAssign};

/// Token counts recorded for one or more LLM invocations.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[must_use]
pub struct Usage {
    /// Tokens generated by the model.
    pub completion_tokens: u64,
    /// Total prompt tokens sent to the model.
    pub prompt_tokens: u64,
    /// Prompt tokens served from provider prompt cache.
    pub cached_prompt_tokens: u64,
    /// Prompt tokens previously seen in the conversation history.
    pub seen_prompt_tokens: u64,
}

impl Usage {
    /// Creates a new [`Usage`] record with zero cached/seen tokens.
    pub const fn new(prompt_tokens: u64, completion_tokens: u64) -> Self {
        Self {
            completion_tokens,
            prompt_tokens,
            cached_prompt_tokens: 0,
            seen_prompt_tokens: 0,
        }
    }

    /// Returns prompt tokens not yet seen in prior turns.
    pub const fn new_prompt_tokens(&self) -> u64 {
        self.prompt_tokens.saturating_sub(self.seen_prompt_tokens)
    }

    /// Returns the sum of prompt and completion tokens.
    pub const fn total_tokens(&self) -> u64 {
        self.prompt_tokens.saturating_add(self.completion_tokens)
    }
}

impl Add for Usage {
    type Output = Self;

    fn add(self, rhs: Self) -> Self::Output {
        Self {
            completion_tokens: self.completion_tokens.saturating_add(rhs.completion_tokens),
            prompt_tokens: self.prompt_tokens.saturating_add(rhs.prompt_tokens),
            cached_prompt_tokens: self
                .cached_prompt_tokens
                .saturating_add(rhs.cached_prompt_tokens),
            seen_prompt_tokens: self
                .seen_prompt_tokens
                .saturating_add(rhs.seen_prompt_tokens),
        }
    }
}

impl AddAssign for Usage {
    fn add_assign(&mut self, rhs: Self) {
        *self = *self + rhs;
    }
}

/// Per-million-token pricing for estimating cloud vs local collaboration savings.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
pub struct ModelPricing {
    /// USD per 1M input (prompt) tokens.
    pub input_per_million_usd: f64,
    /// USD per 1M cached input tokens.
    pub cached_input_per_million_usd: f64,
    /// USD per 1M output (completion) tokens.
    pub output_per_million_usd: f64,
}

impl ModelPricing {
    /// Approximate frontier cloud pricing (e.g. Claude Sonnet / GPT-4o class).
    pub const fn frontier_default() -> Self {
        Self {
            input_per_million_usd: 3.00,
            cached_input_per_million_usd: 0.30,
            output_per_million_usd: 15.00,
        }
    }

    /// Zero-cost local model pricing (on-device Ollama / MLX / llama.cpp).
    pub const fn local_free() -> Self {
        Self {
            input_per_million_usd: 0.0,
            cached_input_per_million_usd: 0.0,
            output_per_million_usd: 0.0,
        }
    }
}

/// Estimates USD cost for a [`Usage`] record under [`ModelPricing`].
#[must_use]
pub fn estimate_cost_usd(usage: Usage, pricing: ModelPricing) -> f64 {
    let uncached_prompt = usage
        .prompt_tokens
        .saturating_sub(usage.cached_prompt_tokens) as f64;
    let cached_prompt = usage.cached_prompt_tokens as f64;
    let completion = usage.completion_tokens as f64;

    (uncached_prompt * pricing.input_per_million_usd
        + cached_prompt * pricing.cached_input_per_million_usd
        + completion * pricing.output_per_million_usd)
        / 1_000_000.0
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn usage_addition_and_new_tokens() {
        let a = Usage {
            completion_tokens: 100,
            prompt_tokens: 500,
            cached_prompt_tokens: 200,
            seen_prompt_tokens: 150,
        };
        let b = Usage::new(300, 50);
        let sum = a + b;
        assert_eq!(sum.prompt_tokens, 800);
        assert_eq!(sum.completion_tokens, 150);
        assert_eq!(sum.total_tokens(), 950);
        assert_eq!(a.new_prompt_tokens(), 350);
    }

    #[test]
    fn cost_estimation_accounts_for_cache() {
        let usage = Usage {
            prompt_tokens: 1_000_000,
            cached_prompt_tokens: 500_000,
            completion_tokens: 100_000,
            seen_prompt_tokens: 0,
        };
        let cost = estimate_cost_usd(usage, ModelPricing::frontier_default());
        // 0.5M * $3 + 0.5M * $0.30 + 0.1M * $15 = 1.5 + 0.15 + 1.5 = $3.15
        assert!((cost - 3.15).abs() < 1e-6);
    }
}

#[cfg(kani)]
mod kani_proofs {
    use super::*;

    fn any_usage() -> Usage {
        Usage {
            completion_tokens: kani::any(),
            prompt_tokens: kani::any(),
            cached_prompt_tokens: kani::any(),
            seen_prompt_tokens: kani::any(),
        }
    }

    #[kani::proof]
    fn verify_usage_addition_no_overflow() {
        let a = any_usage();
        let b = any_usage();
        let sum = a + b;
        let mut assigned = a;
        assigned += b;
        assert_eq!(sum, assigned);
        let _ = sum.total_tokens();
        assert!(sum.prompt_tokens >= a.prompt_tokens);
        assert!(sum.completion_tokens >= a.completion_tokens);
    }

    #[kani::proof]
    fn verify_usage_new_prompt_tokens_bounded() {
        let u = any_usage();
        assert!(u.new_prompt_tokens() <= u.prompt_tokens);
    }

    #[kani::proof]
    fn verify_estimate_cost_non_negative() {
        let u = Usage {
            completion_tokens: kani::any::<u32>() as u64,
            prompt_tokens: kani::any::<u32>() as u64,
            cached_prompt_tokens: kani::any::<u32>() as u64,
            seen_prompt_tokens: 0,
        };
        let cost = estimate_cost_usd(u, ModelPricing::frontier_default());
        assert!(!cost.is_nan());
        assert!(cost >= 0.0);
    }
}
